const double quantized = std::max(1.0, std::round(scale * 8.0) / 8.0);
const double rounded = std::round(logical_height * quantized);
// 범위를 검사한 다음 정수로 바꾼다.
const int device_height = static_cast<int>(rounded);
const float logical_per_device = float(logical_height) / device_height;

std::optional<HorizontalMetrics> horizontal(char32_t scalar, float height) const;
std::optional<Glyph> rasterize_device(char32_t scalar, int height) const;
// Font의 private 구현:
std::optional<Glyph> rasterize_impl(char32_t scalar, float height) const;

bool load_trusted(const std::filesystem::path& path) {
    if (!font_.load_trusted(path)) return false;
    clear();
    return true;
}

auto metrics = font_.horizontal(scalar, plan.logical_height);
if (!metrics) return nullptr;
++stats_.raster_attempts;
auto bitmap = font_.rasterize_device(scalar, plan.device_height);
if (!bitmap) return nullptr;
// shared_ptr 할당까지 성공한 뒤 entries_[slot]에 저장한다.

const auto revision = atlas_.revision();
if (revision != cached_revision_) {
    release_lookup();
    cached_revision_ = revision;
}
if (revision == 0 || !glyph) return std::nullopt;
// 동일 스냅샷 hit → 저장한 Region
// miss → atlas_.insert(glyph->bitmap), 성공 뒤에만 lookup 확정

const auto& b = glyph->bitmap;
const float ratio = glyph->logical_per_device;
study_layout::Box box{b.xoff * ratio, b.yoff * ratio,
                      b.width * ratio, b.height * ratio};
layout.add(glyph->advance, kern_before, box);

const double density = double(layout->viewport.height) / layout->logical.height;
const auto plan = font_raster::plan(0, 16, density);
if (!plan) return 1;
if (plan->device_height != prepared_height) {
    // 전체 라벨을 해제하고 페이지를 한 번 비운 뒤 함께 준비한다.
    // 모두 성공한 뒤 prepared_height를 갱신한다.
}

const auto before = cache.stats().raster_attempts;
auto second = prepare_cached_paragraph(cache, label, 22, 2.0);
// 같은 문단을 먼저 준비했다면:
// cache.stats().raster_attempts == before
